def dem_tu(text):
    dem = {}
    for w in text.lower().split():
        dem[w] = dem.get(w, 0) + 1
    return dem

def bo_trung(xs):
    da_gap = set()
    kq = []
    for x in xs:
        if x not in da_gap:
            da_gap.add(x)
            kq.append(x)
    return kq

def top_k(diem, k):
    xep = sorted(diem.items(), key=lambda x: (-x[1], x[0]))
    return [ten for ten, _ in xep[:k]]

def co_cap_tong(nums, k):
    da_gap = set()
    for x in nums:
        if k - x in da_gap:
            return True
        da_gap.add(x)
    return False

def tong_theo_user(records):
    tong = {}
    for r in records:
        a = r.get("amount")
        if a is None:
            continue
        tong[r["user"]] = tong.get(r["user"], 0) + a
    return tong

def doanh_thu_top(df, k):
    return (df.assign(doanh_thu=df["so_luong"] * df["don_gia"])
              .groupby("danh_muc", as_index=False)["doanh_thu"].sum()
              .sort_values(["doanh_thu", "danh_muc"], ascending=[False, True])
              .head(k)
              .reset_index(drop=True))
